public String buildCondensed() {
        String status = "";
        if(validNotificationsResponse() && validInboxResponse()) {
            status = String.valueOf(notificationResponse.count + inboxResponse.count);
        } else if(validNotificationsResponse()) {
            status = String.valueOf(notificationResponse.count);
        } else if(validInboxResponse()) {
            status = String.valueOf(inboxResponse.count);
        }
        return status;
    }
